from pathlib import Path
import shutil

ROOT = Path(".")
FRONT = ROOT / "frontend"

if not FRONT.exists():
    raise SystemExit(
        "Não encontrei a pasta frontend. Rode este script na raiz do Mentor.Edu."
    )

CSS_NAME = "mentor-ai-student.css"
JS_NAME = "mentor-ai-student.js"

css_path = FRONT / CSS_NAME
js_path = FRONT / JS_NAME

CSS = '\n/* Mentor.Edu — IA Aluno V1 */\n:root{\n  --mentor-ai-primary:#6d38f5;\n  --mentor-ai-primary-2:#4f46e5;\n  --mentor-ai-ink:#17203a;\n  --mentor-ai-muted:#6b7280;\n  --mentor-ai-line:#e7e9f2;\n  --mentor-ai-card:#ffffff;\n  --mentor-ai-soft:#f6f3ff;\n  --mentor-ai-shadow:0 12px 30px rgba(53, 43, 101, .12);\n}\n\n.mentor-ai-hidden{display:none!important}\n\n/* Card compacto no Início */\n#mentor-ai-home-card{\n  width:100%;\n  box-sizing:border-box;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:18px;\n  min-height:84px;\n  padding:14px 18px;\n  margin:14px 0 18px;\n  border:1px solid var(--mentor-ai-line);\n  border-radius:18px;\n  background:linear-gradient(135deg,#fff 0%,#fbfaff 62%,#f3efff 100%);\n  box-shadow:0 7px 22px rgba(77,54,155,.08);\n}\n.mentor-ai-home-left{\n  display:flex;align-items:center;gap:14px;min-width:0;\n}\n.mentor-ai-mascot{\n  width:54px;height:54px;flex:0 0 54px;\n  border-radius:16px;\n  display:grid;place-items:center;\n  background:linear-gradient(145deg,#e9f8ff,#efe8ff);\n  border:1px solid #dce7ff;\n  font-size:30px;\n  box-shadow:inset 0 0 0 4px rgba(255,255,255,.55);\n}\n.mentor-ai-home-copy{min-width:0}\n.mentor-ai-home-title{\n  margin:0;font-weight:800;font-size:18px;color:var(--mentor-ai-ink);\n}\n.mentor-ai-home-subtitle{\n  margin:3px 0 0;color:var(--mentor-ai-muted);font-size:13px;\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\n}\n.mentor-ai-home-action{\n  flex:0 0 auto;border:0;cursor:pointer;\n  padding:11px 18px;border-radius:999px;\n  background:linear-gradient(135deg,var(--mentor-ai-primary),var(--mentor-ai-primary-2));\n  color:#fff;font-weight:800;font-size:13px;\n  box-shadow:0 8px 18px rgba(109,56,245,.22);\n}\n.mentor-ai-home-action:hover{transform:translateY(-1px)}\n\n/* Item de menu injetado */\n#mentor-ai-nav-item{\n  cursor:pointer;\n}\n#mentor-ai-nav-item .mentor-ai-nav-icon{\n  width:22px;height:22px;border-radius:7px;display:inline-grid;place-items:center;\n  background:#f1ebff;color:var(--mentor-ai-primary);font-size:13px;\n}\n\n/* Assistente flutuante */\n#mentor-ai-floating{\n  position:fixed;\n  right:24px;\n  bottom:24px;\n  z-index:2147482000;\n  display:flex;\n  align-items:center;\n  gap:10px;\n  border:0;\n  cursor:pointer;\n  padding:8px 14px 8px 8px;\n  border-radius:999px;\n  color:#fff;\n  background:linear-gradient(135deg,#302a7e,#6d38f5);\n  box-shadow:0 14px 34px rgba(44,35,115,.30);\n  transition:.18s ease;\n}\n#mentor-ai-floating:hover{transform:translateY(-2px)}\n#mentor-ai-floating .mentor-ai-float-avatar{\n  width:38px;height:38px;border-radius:50%;\n  display:grid;place-items:center;\n  background:#fff;color:#302a7e;font-size:23px;\n}\n#mentor-ai-floating .mentor-ai-float-copy{\n  text-align:left;line-height:1.05;font-weight:800;font-size:13px;\n}\n#mentor-ai-floating .mentor-ai-badge{\n  position:absolute;right:-3px;top:-4px;\n  min-width:20px;height:20px;padding:0 5px;\n  display:grid;place-items:center;\n  border-radius:999px;background:#ff3b3b;color:#fff;\n  font-size:11px;font-weight:900;border:2px solid #fff;\n}\n\n#mentor-ai-nudge{\n  position:fixed;\n  right:24px;\n  bottom:88px;\n  z-index:2147481999;\n  width:min(360px,calc(100vw - 32px));\n  background:#fff;\n  border:1px solid var(--mentor-ai-line);\n  border-radius:18px;\n  box-shadow:var(--mentor-ai-shadow);\n  padding:15px;\n  box-sizing:border-box;\n}\n#mentor-ai-nudge h4{margin:0 0 7px;color:var(--mentor-ai-ink);font-size:15px}\n#mentor-ai-nudge p{margin:0 0 12px;color:#565f70;font-size:13px;line-height:1.45}\n.mentor-ai-nudge-actions{display:flex;gap:8px}\n.mentor-ai-nudge-actions button{\n  border:1px solid #ded8ff;background:#fff;color:var(--mentor-ai-primary);\n  border-radius:11px;padding:9px 11px;font-weight:750;cursor:pointer;font-size:12px;\n}\n.mentor-ai-nudge-actions .primary{\n  background:var(--mentor-ai-primary);color:#fff;border-color:var(--mentor-ai-primary);\n}\n\n/* Área completa Mentor Edu */\n#mentor-ai-overlay{\n  position:fixed;inset:0;z-index:2147483000;\n  background:rgba(13,18,38,.32);\n  backdrop-filter:blur(3px);\n  display:flex;align-items:stretch;justify-content:flex-end;\n}\n#mentor-ai-panel{\n  width:min(1180px,calc(100vw - 70px));\n  height:100%;\n  background:#f8f9fd;\n  box-shadow:-18px 0 45px rgba(28,32,58,.18);\n  display:grid;\n  grid-template-rows:auto auto 1fr;\n  overflow:hidden;\n}\n.mentor-ai-panel-head{\n  display:flex;align-items:center;justify-content:space-between;\n  padding:18px 22px;\n  background:#fff;border-bottom:1px solid var(--mentor-ai-line);\n}\n.mentor-ai-panel-title{\n  display:flex;align-items:center;gap:12px;color:var(--mentor-ai-ink);\n}\n.mentor-ai-panel-title strong{display:block;font-size:20px}\n.mentor-ai-panel-title small{display:block;color:var(--mentor-ai-muted);margin-top:2px}\n.mentor-ai-close{\n  width:38px;height:38px;border-radius:12px;border:1px solid var(--mentor-ai-line);\n  background:#fff;cursor:pointer;font-size:20px;color:#4b5563;\n}\n.mentor-ai-tabs{\n  display:flex;gap:8px;padding:12px 18px;background:#fff;border-bottom:1px solid var(--mentor-ai-line);\n}\n.mentor-ai-tab{\n  border:1px solid #e6e4f2;background:#fff;color:#5b6476;\n  border-radius:999px;padding:9px 14px;font-weight:800;cursor:pointer;font-size:13px;\n}\n.mentor-ai-tab.active{\n  background:#f0ebff;border-color:#d7caff;color:var(--mentor-ai-primary);\n}\n.mentor-ai-view{display:none;height:100%;overflow:auto}\n.mentor-ai-view.active{display:block}\n\n/* Chat */\n.mentor-ai-chat-layout{\n  display:grid;grid-template-columns:280px 1fr;height:100%;min-height:0;\n}\n.mentor-ai-history{\n  border-right:1px solid var(--mentor-ai-line);background:#fff;padding:16px;overflow:auto;\n}\n.mentor-ai-history-head{\n  display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;\n}\n.mentor-ai-history-head strong{color:var(--mentor-ai-ink)}\n.mentor-ai-new-chat{\n  border:0;background:#f1ebff;color:var(--mentor-ai-primary);font-weight:900;\n  border-radius:10px;padding:8px 10px;cursor:pointer;\n}\n.mentor-ai-history-item{\n  width:100%;text-align:left;border:1px solid transparent;background:transparent;\n  border-radius:12px;padding:10px;margin:0 0 6px;cursor:pointer;color:#495164;\n}\n.mentor-ai-history-item:hover,.mentor-ai-history-item.active{\n  background:#f7f4ff;border-color:#e6dcff;color:#33246b;\n}\n.mentor-ai-history-item b{display:block;font-size:13px;margin-bottom:3px}\n.mentor-ai-history-item small{font-size:11px;color:#8a91a1}\n\n.mentor-ai-chat-main{\n  display:grid;grid-template-rows:1fr auto;min-width:0;min-height:0;\n}\n#mentor-ai-messages{\n  padding:24px;overflow:auto;min-height:0;\n}\n.mentor-ai-welcome{\n  max-width:620px;margin:25px auto;text-align:center;\n  color:var(--mentor-ai-ink);\n}\n.mentor-ai-welcome .mentor-ai-big-mascot{\n  width:84px;height:84px;margin:0 auto 12px;border-radius:26px;\n  display:grid;place-items:center;font-size:48px;\n  background:linear-gradient(145deg,#eaf8ff,#efe9ff);\n  border:1px solid #dce7ff;\n}\n.mentor-ai-welcome h2{margin:0 0 7px}\n.mentor-ai-welcome p{margin:0;color:var(--mentor-ai-muted)}\n.mentor-ai-quick-actions{\n  display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;\n  margin:18px auto 0;max-width:660px;\n}\n.mentor-ai-quick-action{\n  border:1px solid #e3e5ed;background:#fff;border-radius:14px;padding:12px;\n  text-align:left;cursor:pointer;color:#2f3749;font-weight:750;\n}\n.mentor-ai-quick-action:hover{border-color:#cabaff;background:#fbf9ff}\n.mentor-ai-msg{\n  display:flex;margin:0 0 14px;\n}\n.mentor-ai-msg.user{justify-content:flex-end}\n.mentor-ai-msg .bubble{\n  max-width:min(720px,82%);\n  border-radius:17px;padding:12px 14px;line-height:1.55;font-size:14px;\n  white-space:pre-wrap;word-break:break-word;\n}\n.mentor-ai-msg.user .bubble{\n  background:linear-gradient(135deg,#6d38f5,#5146df);color:#fff;border-bottom-right-radius:5px;\n}\n.mentor-ai-msg.ai .bubble{\n  background:#fff;color:#293244;border:1px solid var(--mentor-ai-line);border-bottom-left-radius:5px;\n}\n.mentor-ai-thinking{opacity:.72;font-style:italic}\n.mentor-ai-composer{\n  display:flex;gap:10px;align-items:flex-end;\n  padding:14px;background:#fff;border-top:1px solid var(--mentor-ai-line);\n}\n#mentor-ai-input{\n  flex:1;resize:none;min-height:44px;max-height:130px;\n  border:1px solid #dfe3ec;border-radius:14px;padding:12px 14px;\n  font:inherit;outline:none;box-sizing:border-box;\n}\n#mentor-ai-input:focus{border-color:#b9a7ff;box-shadow:0 0 0 3px rgba(109,56,245,.08)}\n#mentor-ai-send{\n  width:46px;height:46px;border-radius:14px;border:0;cursor:pointer;\n  background:var(--mentor-ai-primary);color:#fff;font-size:19px;font-weight:900;\n}\n\n/* Insights/área interna */\n.mentor-ai-insights{padding:20px}\n.mentor-ai-summary-grid{\n  display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:14px;\n}\n.mentor-ai-summary-card,.mentor-ai-accordion{\n  background:#fff;border:1px solid var(--mentor-ai-line);border-radius:16px;\n  box-shadow:0 5px 18px rgba(48,52,86,.05);\n}\n.mentor-ai-summary-card{padding:15px}\n.mentor-ai-summary-card h4{margin:0 0 6px;color:var(--mentor-ai-ink)}\n.mentor-ai-summary-card p{margin:0;color:#5d6576;font-size:13px;line-height:1.45}\n.mentor-ai-accordion{margin-bottom:10px;overflow:hidden}\n.mentor-ai-accordion button{\n  width:100%;display:flex;justify-content:space-between;align-items:center;\n  background:#fff;border:0;padding:14px 16px;cursor:pointer;text-align:left;\n  color:var(--mentor-ai-ink);font-weight:850;\n}\n.mentor-ai-accordion-content{\n  display:none;padding:0 16px 16px;color:#5c6474;font-size:13px;line-height:1.5;\n}\n.mentor-ai-accordion.open .mentor-ai-accordion-content{display:block}\n.mentor-ai-dot{\n  display:inline-grid;place-items:center;min-width:20px;height:20px;border-radius:999px;\n  background:#ff3b3b;color:#fff;font-size:11px;margin-left:7px;\n}\n\n/* Mobile */\n@media (max-width:760px){\n  #mentor-ai-home-card{min-height:92px;padding:12px 13px;gap:10px}\n  .mentor-ai-home-subtitle{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}\n  .mentor-ai-home-action{padding:10px 12px;font-size:12px}\n  #mentor-ai-floating{\n    right:15px;bottom:76px;padding:7px;\n  }\n  #mentor-ai-floating .mentor-ai-float-copy{display:none}\n  #mentor-ai-floating .mentor-ai-float-avatar{width:42px;height:42px}\n  #mentor-ai-nudge{right:12px;bottom:132px}\n  #mentor-ai-panel{width:100vw}\n  .mentor-ai-chat-layout{grid-template-columns:1fr}\n  .mentor-ai-history{display:none}\n  .mentor-ai-summary-grid{grid-template-columns:1fr}\n  .mentor-ai-panel-head{padding:13px 14px}\n  .mentor-ai-tabs{overflow-x:auto;white-space:nowrap;padding:9px 12px}\n  #mentor-ai-messages{padding:15px}\n  .mentor-ai-quick-actions{grid-template-columns:1fr}\n  .mentor-ai-msg .bubble{max-width:90%}\n}\n'
JS = '\n(() => {\n  "use strict";\n\n  const CFG = {\n    profileUrl: "/mentor-ai/student/profile",\n    tutorUrl: "/mentor-ai/student/tutor",\n    storageHistory: "mentorEdu.ai.student.history.v1",\n    storageSettings: "mentorEdu.ai.student.settings.v1"\n  };\n\n  const $ = (s, root=document) => root.querySelector(s);\n  const $$ = (s, root=document) => Array.from(root.querySelectorAll(s));\n\n  function textOf(el){ return (el?.textContent || "").trim(); }\n  function normalize(s){\n    return String(s || "").normalize("NFD").replace(/[\\u0300-\\u036f]/g,"").toLowerCase();\n  }\n\n  function detectRole(){\n    const stores = [localStorage, sessionStorage];\n    const directKeys = ["role","user_role","perfil","tipo_usuario","userType","user_type"];\n    for(const store of stores){\n      for(const key of directKeys){\n        const v = normalize(store.getItem(key));\n        if(v.includes("student") || v.includes("aluno")) return "student";\n        if(v.includes("professor") || v.includes("teacher")) return "teacher";\n        if(v.includes("admin")) return "admin";\n      }\n      for(let i=0;i<store.length;i++){\n        const key = store.key(i);\n        const raw = store.getItem(key);\n        if(!raw || raw.length > 12000) continue;\n        try{\n          const obj = JSON.parse(raw);\n          const pool = normalize(JSON.stringify({\n            role: obj?.role,\n            perfil: obj?.perfil,\n            type: obj?.type,\n            user_type: obj?.user_type,\n            tipo_usuario: obj?.tipo_usuario\n          }));\n          if(pool.includes("student") || pool.includes("aluno")) return "student";\n          if(pool.includes("professor") || pool.includes("teacher")) return "teacher";\n          if(pool.includes("admin")) return "admin";\n        }catch{}\n      }\n    }\n    return "unknown";\n  }\n\n  function looksLikeStudentDashboard(){\n    const body = normalize(document.body?.innerText || "");\n    const studentSignals = ["disciplinas","avaliacoes","notas","frequencia","biblioteca","horarios"];\n    const count = studentSignals.filter(x => body.includes(x)).length;\n    return count >= 3;\n  }\n\n  function shouldMount(){\n    const role = detectRole();\n    if(role === "teacher" || role === "admin") return false;\n    if(role === "student") return true;\n    return looksLikeStudentDashboard();\n  }\n\n  function findToken(){\n    const stores = [localStorage, sessionStorage];\n    const keys = [\n      "access_token","accessToken","token","auth_token","authToken",\n      "jwt","mentor_token","mentorEduToken"\n    ];\n    for(const store of stores){\n      for(const key of keys){\n        const v = store.getItem(key);\n        if(v && v.length > 20 && !v.startsWith("{")) return v.replace(/^Bearer\\s+/i,"");\n      }\n      for(let i=0;i<store.length;i++){\n        const raw = store.getItem(store.key(i));\n        if(!raw || raw.length > 12000) continue;\n        try{\n          const obj = JSON.parse(raw);\n          for(const key of keys){\n            const v = obj?.[key];\n            if(typeof v === "string" && v.length > 20) return v.replace(/^Bearer\\s+/i,"");\n          }\n        }catch{}\n      }\n    }\n    return "";\n  }\n\n  function apiHeaders(){\n    const token = findToken();\n    const h = {"Content-Type":"application/json"};\n    if(token) h.Authorization = `Bearer ${token}`;\n    return h;\n  }\n\n  function safeJsonParse(raw, fallback){\n    try{return JSON.parse(raw)}catch{return fallback}\n  }\n\n  function loadSettings(){\n    return safeJsonParse(localStorage.getItem(CFG.storageSettings), {\n      floatingEnabled:true,\n      nudgeSeen:false\n    });\n  }\n\n  function saveSettings(v){\n    localStorage.setItem(CFG.storageSettings, JSON.stringify(v));\n  }\n\n  function loadHistory(){\n    const data = safeJsonParse(localStorage.getItem(CFG.storageHistory), []);\n    return Array.isArray(data) ? data : [];\n  }\n\n  function saveHistory(data){\n    localStorage.setItem(CFG.storageHistory, JSON.stringify(data.slice(-20)));\n  }\n\n  let state = {\n    settings: loadSettings(),\n    history: loadHistory(),\n    currentId: null,\n    profile: null,\n    lowestSubject: null\n  };\n\n  function escapeHtml(s){\n    return String(s ?? "").replace(/[&<>"\']/g, c => ({\n      "&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#039;"\n    }[c]));\n  }\n\n  function findHeading(text){\n    const wanted = normalize(text);\n    return $$("h1,h2,h3,h4,h5,h6,p,span,strong,div").find(el => {\n      const t = normalize(textOf(el));\n      return t === wanted;\n    });\n  }\n\n  function findShortcutsSection(){\n    const h = findHeading("Atalhos rápidos") || findHeading("Atalhos rapidos");\n    if(!h) return null;\n    let el = h;\n    for(let i=0;i<5 && el;i++,el=el.parentElement){\n      const t = normalize(textOf(el));\n      if(t.includes("atalhos rapidos") && (t.includes("disciplinas") || t.includes("avaliacoes"))) return el;\n    }\n    return h.parentElement;\n  }\n\n  function createHomeCard(){\n    if($("#mentor-ai-home-card")) return;\n    const shortcuts = findShortcutsSection();\n    if(!shortcuts) return;\n\n    const card = document.createElement("section");\n    card.id = "mentor-ai-home-card";\n    card.innerHTML = `\n      <div class="mentor-ai-home-left">\n        <div class="mentor-ai-mascot" aria-hidden="true">🤖</div>\n        <div class="mentor-ai-home-copy">\n          <p class="mentor-ai-home-title">Mentor Edu</p>\n          <p class="mentor-ai-home-subtitle">Converse, tire dúvidas e receba orientação personalizada de estudos.</p>\n        </div>\n      </div>\n      <button class="mentor-ai-home-action" type="button">💬 Conversar com o Mentor</button>\n    `;\n    card.querySelector("button").addEventListener("click", () => openMentor("chat"));\n    shortcuts.parentElement.insertBefore(card, shortcuts);\n  }\n\n  function createFloating(){\n    if($("#mentor-ai-floating")) return;\n\n    const btn = document.createElement("button");\n    btn.id = "mentor-ai-floating";\n    btn.type = "button";\n    btn.innerHTML = `\n      <span class="mentor-ai-float-avatar">🤖</span>\n      <span class="mentor-ai-float-copy">O que vamos<br>fazer hoje?</span>\n      <span class="mentor-ai-badge">1</span>\n    `;\n    btn.addEventListener("click", toggleNudge);\n    document.body.appendChild(btn);\n\n    if(!state.settings.floatingEnabled) btn.classList.add("mentor-ai-hidden");\n  }\n\n  function toggleNudge(){\n    let nudge = $("#mentor-ai-nudge");\n    if(nudge){ nudge.remove(); return; }\n\n    const subject = state.lowestSubject || "uma disciplina";\n    nudge = document.createElement("div");\n    nudge.id = "mentor-ai-nudge";\n    nudge.innerHTML = `\n      <h4>✨ Sugestão do Mentor</h4>\n      <p>Percebi que <strong>${escapeHtml(subject)}</strong> pode merecer mais atenção. Quer estudar isso comigo?</p>\n      <div class="mentor-ai-nudge-actions">\n        <button type="button" data-action="close">Agora não</button>\n        <button type="button" class="primary" data-action="open">Conversar</button>\n      </div>\n    `;\n    nudge.addEventListener("click", e => {\n      const action = e.target?.dataset?.action;\n      if(action === "close") nudge.remove();\n      if(action === "open"){ nudge.remove(); openMentor("chat"); }\n    });\n    document.body.appendChild(nudge);\n  }\n\n  function createNavItem(){\n    if($("#mentor-ai-nav-item")) return;\n\n    const candidates = $$("a,button,li,div").filter(el => {\n      const t = normalize(textOf(el));\n      return t === "desempenho" || t === "disciplinas";\n    });\n\n    let ref = candidates.find(el => {\n      const parentText = normalize(textOf(el.parentElement));\n      return parentText.includes("inicio") && parentText.includes("configuracoes");\n    }) || candidates[0];\n\n    if(!ref) return;\n\n    const clickable = ref.matches("a,button,li") ? ref : ref.closest("a,button,li") || ref;\n    const parent = clickable.parentElement;\n    if(!parent) return;\n\n    let item;\n    if(clickable.tagName === "A"){\n      item = clickable.cloneNode(true);\n      item.removeAttribute("href");\n      item.querySelectorAll("[id]").forEach(n => n.removeAttribute("id"));\n      const txtNodes = Array.from(item.querySelectorAll("*")).reverse();\n      const label = txtNodes.find(n => normalize(textOf(n)) === normalize(textOf(clickable)));\n      if(label) label.textContent = "Mentor Edu";\n      else item.textContent = "🤖 Mentor Edu";\n    }else{\n      item = document.createElement(clickable.tagName === "LI" ? "li" : "button");\n      item.type = item.tagName === "BUTTON" ? "button" : undefined;\n      item.innerHTML = `<span class="mentor-ai-nav-icon">🤖</span><span>Mentor Edu</span>`;\n    }\n\n    item.id = "mentor-ai-nav-item";\n    item.addEventListener("click", e => {\n      e.preventDefault();\n      openMentor("chat");\n    });\n\n    clickable.insertAdjacentElement("afterend", item);\n  }\n\n  function createOverlay(){\n    if($("#mentor-ai-overlay")) return;\n\n    const overlay = document.createElement("div");\n    overlay.id = "mentor-ai-overlay";\n    overlay.className = "mentor-ai-hidden";\n    overlay.innerHTML = `\n      <section id="mentor-ai-panel" role="dialog" aria-modal="true" aria-label="Mentor Edu">\n        <header class="mentor-ai-panel-head">\n          <div class="mentor-ai-panel-title">\n            <div class="mentor-ai-mascot">🤖</div>\n            <div><strong>Mentor Edu</strong><small>Seu tutor inteligente</small></div>\n          </div>\n          <button class="mentor-ai-close" type="button" aria-label="Fechar">×</button>\n        </header>\n\n        <nav class="mentor-ai-tabs">\n          <button class="mentor-ai-tab active" data-view="chat" type="button">💬 Chat</button>\n          <button class="mentor-ai-tab" data-view="insights" type="button">✨ Meu aprendizado</button>\n          <button class="mentor-ai-tab" data-view="history" type="button">🕘 Conversas</button>\n        </nav>\n\n        <div>\n          <section class="mentor-ai-view active" data-view-panel="chat">\n            <div class="mentor-ai-chat-layout">\n              <aside class="mentor-ai-history">\n                <div class="mentor-ai-history-head">\n                  <strong>Conversas</strong>\n                  <button class="mentor-ai-new-chat" type="button">+ Novo</button>\n                </div>\n                <div id="mentor-ai-history-list"></div>\n              </aside>\n              <main class="mentor-ai-chat-main">\n                <div id="mentor-ai-messages"></div>\n                <form class="mentor-ai-composer" id="mentor-ai-form">\n                  <textarea id="mentor-ai-input" rows="1" placeholder="Digite sua dúvida..."></textarea>\n                  <button id="mentor-ai-send" type="submit" aria-label="Enviar">➤</button>\n                </form>\n              </main>\n            </div>\n          </section>\n\n          <section class="mentor-ai-view" data-view-panel="insights">\n            <div class="mentor-ai-insights">\n              <div class="mentor-ai-summary-grid">\n                <article class="mentor-ai-summary-card">\n                  <h4>👍 Pontos fortes</h4>\n                  <p id="mentor-ai-strong">Carregando seu perfil...</p>\n                </article>\n                <article class="mentor-ai-summary-card">\n                  <h4>🎯 Pontos para melhorar</h4>\n                  <p id="mentor-ai-improve">Carregando seu perfil...</p>\n                </article>\n                <article class="mentor-ai-summary-card">\n                  <h4>💡 Sugestão do Mentor</h4>\n                  <p id="mentor-ai-suggestion">Vou usar seu desempenho para sugerir o próximo passo.</p>\n                </article>\n              </div>\n\n              <div class="mentor-ai-accordion">\n                <button type="button"><span>📅 Plano de estudos da semana</span><span>⌄</span></button>\n                <div class="mentor-ai-accordion-content">\n                  Aqui ficará o plano semanal personalizado. A IA do cronograma será conectada em uma etapa posterior.\n                </div>\n              </div>\n\n              <div class="mentor-ai-accordion">\n                <button type="button"><span>🔔 Alertas inteligentes <span class="mentor-ai-dot">1</span></span><span>⌄</span></button>\n                <div class="mentor-ai-accordion-content" id="mentor-ai-alert-content">\n                  Assim que os dados do aluno forem analisados, os alertas aparecem aqui sem poluir a tela inicial.\n                </div>\n              </div>\n\n              <div class="mentor-ai-accordion">\n                <button type="button"><span>📊 Recomendações da IA</span><span>⌄</span></button>\n                <div class="mentor-ai-accordion-content" id="mentor-ai-recommend-content">\n                  Recomendações pedagógicas personalizadas com base em notas, frequência e dificuldades.\n                </div>\n              </div>\n\n              <div class="mentor-ai-accordion">\n                <button type="button"><span>⚙️ Assistente flutuante com IA</span><span>⌄</span></button>\n                <div class="mentor-ai-accordion-content">\n                  <label style="display:flex;align-items:center;gap:10px;cursor:pointer">\n                    <input id="mentor-ai-floating-toggle" type="checkbox">\n                    Mostrar sugestões flutuantes enquanto navego\n                  </label>\n                </div>\n              </div>\n            </div>\n          </section>\n\n          <section class="mentor-ai-view" data-view-panel="history">\n            <div class="mentor-ai-insights">\n              <h3 style="margin-top:0;color:#17203a">Histórico de conversas</h3>\n              <div id="mentor-ai-history-full"></div>\n            </div>\n          </section>\n        </div>\n      </section>\n    `;\n\n    overlay.addEventListener("click", e => {\n      if(e.target === overlay) closeMentor();\n    });\n    overlay.querySelector(".mentor-ai-close").addEventListener("click", closeMentor);\n    overlay.querySelectorAll(".mentor-ai-tab").forEach(btn => {\n      btn.addEventListener("click", () => setView(btn.dataset.view));\n    });\n    overlay.querySelectorAll(".mentor-ai-accordion > button").forEach(btn => {\n      btn.addEventListener("click", () => btn.parentElement.classList.toggle("open"));\n    });\n    overlay.querySelector(".mentor-ai-new-chat").addEventListener("click", newChat);\n    overlay.querySelector("#mentor-ai-form").addEventListener("submit", sendMessage);\n\n    document.body.appendChild(overlay);\n    syncFloatingToggle();\n    renderHistory();\n    renderMessages();\n  }\n\n  function openMentor(view="chat"){\n    createOverlay();\n    $("#mentor-ai-overlay")?.classList.remove("mentor-ai-hidden");\n    document.body.style.overflow = "hidden";\n    setView(view);\n    renderHistory();\n    renderMessages();\n    fetchProfile();\n    setTimeout(() => $("#mentor-ai-input")?.focus(), 80);\n  }\n\n  function closeMentor(){\n    $("#mentor-ai-overlay")?.classList.add("mentor-ai-hidden");\n    document.body.style.overflow = "";\n  }\n\n  function setView(view){\n    $$(".mentor-ai-tab").forEach(x => x.classList.toggle("active", x.dataset.view === view));\n    $$("[data-view-panel]").forEach(x => x.classList.toggle("active", x.dataset.viewPanel === view));\n    if(view === "history") renderFullHistory();\n  }\n\n  function newChat(){\n    state.currentId = `c_${Date.now()}`;\n    state.history.push({\n      id:state.currentId,\n      title:"Nova conversa",\n      createdAt:new Date().toISOString(),\n      messages:[]\n    });\n    saveHistory(state.history);\n    renderHistory();\n    renderMessages();\n    $("#mentor-ai-input")?.focus();\n  }\n\n  function currentConversation(){\n    let conv = state.history.find(c => c.id === state.currentId);\n    if(!conv){\n      if(state.history.length){\n        conv = state.history[state.history.length - 1];\n        state.currentId = conv.id;\n      }else{\n        newChat();\n        conv = state.history[state.history.length - 1];\n      }\n    }\n    return conv;\n  }\n\n  function renderHistory(){\n    const box = $("#mentor-ai-history-list");\n    if(!box) return;\n    const list = [...state.history].reverse();\n    box.innerHTML = list.length ? list.map(c => `\n      <button class="mentor-ai-history-item ${c.id===state.currentId?"active":""}" data-id="${escapeHtml(c.id)}" type="button">\n        <b>${escapeHtml(c.title || "Conversa")}</b>\n        <small>${new Date(c.createdAt).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"})}</small>\n      </button>\n    `).join("") : `<p style="color:#8a91a1;font-size:13px">Nenhuma conversa ainda.</p>`;\n\n    box.querySelectorAll("[data-id]").forEach(btn => {\n      btn.addEventListener("click", () => {\n        state.currentId = btn.dataset.id;\n        renderHistory();\n        renderMessages();\n      });\n    });\n  }\n\n  function renderFullHistory(){\n    const box = $("#mentor-ai-history-full");\n    if(!box) return;\n    const list = [...state.history].reverse();\n    box.innerHTML = list.length ? list.map(c => `\n      <button class="mentor-ai-history-item" data-full-id="${escapeHtml(c.id)}" type="button">\n        <b>${escapeHtml(c.title || "Conversa")}</b>\n        <small>${c.messages?.length || 0} mensagens • ${new Date(c.createdAt).toLocaleString("pt-BR")}</small>\n      </button>\n    `).join("") : `<p style="color:#8a91a1">Nenhuma conversa salva neste navegador.</p>`;\n    box.querySelectorAll("[data-full-id]").forEach(btn => {\n      btn.addEventListener("click", () => {\n        state.currentId = btn.dataset.fullId;\n        setView("chat");\n        renderHistory();\n        renderMessages();\n      });\n    });\n  }\n\n  function renderMessages(){\n    const box = $("#mentor-ai-messages");\n    if(!box) return;\n    const conv = currentConversation();\n    if(!conv.messages.length){\n      box.innerHTML = `\n        <div class="mentor-ai-welcome">\n          <div class="mentor-ai-big-mascot">🤖</div>\n          <h2>Olá! Sou o Mentor Edu.</h2>\n          <p>Posso explicar conteúdos, analisar seu desempenho e ajudar a organizar seus estudos.</p>\n          <div class="mentor-ai-quick-actions">\n            <button class="mentor-ai-quick-action" data-prompt="Explique um conteúdo que estou com dificuldade." type="button">📘 Explicar um conteúdo</button>\n            <button class="mentor-ai-quick-action" data-prompt="Analise meu desempenho e diga onde devo focar." type="button">📊 Analisar meu desempenho</button>\n            <button class="mentor-ai-quick-action" data-prompt="Monte uma sessão de estudos para hoje." type="button">🎯 Montar uma sessão de estudos</button>\n            <button class="mentor-ai-quick-action" data-prompt="Quero resolver um exercício passo a passo." type="button">✏️ Resolver um exercício</button>\n          </div>\n        </div>\n      `;\n      box.querySelectorAll("[data-prompt]").forEach(btn => btn.addEventListener("click", () => {\n        const input = $("#mentor-ai-input");\n        input.value = btn.dataset.prompt;\n        input.focus();\n      }));\n      return;\n    }\n    box.innerHTML = conv.messages.map(m => `\n      <div class="mentor-ai-msg ${m.role==="user"?"user":"ai"}">\n        <div class="bubble">${escapeHtml(m.content)}</div>\n      </div>\n    `).join("");\n    box.scrollTop = box.scrollHeight;\n  }\n\n  async function sendMessage(e){\n    e.preventDefault();\n    const input = $("#mentor-ai-input");\n    const msg = input.value.trim();\n    if(!msg) return;\n\n    const conv = currentConversation();\n    conv.messages.push({role:"user",content:msg,at:new Date().toISOString()});\n    if(!conv.title || conv.title === "Nova conversa"){\n      conv.title = msg.slice(0,42) + (msg.length > 42 ? "…" : "");\n    }\n    input.value = "";\n    saveHistory(state.history);\n    renderHistory();\n    renderMessages();\n\n    const box = $("#mentor-ai-messages");\n    const thinking = document.createElement("div");\n    thinking.className = "mentor-ai-msg ai mentor-ai-thinking";\n    thinking.innerHTML = `<div class="bubble">Mentor está pensando…</div>`;\n    box.appendChild(thinking);\n    box.scrollTop = box.scrollHeight;\n\n    try{\n      const res = await fetch(CFG.tutorUrl,{\n        method:"POST",\n        headers:apiHeaders(),\n        credentials:"same-origin",\n        body:JSON.stringify({mensagem:msg})\n      });\n\n      let data = {};\n      try{ data = await res.json(); }catch{}\n\n      if(!res.ok){\n        throw new Error(data?.detail || `Erro ${res.status}`);\n      }\n\n      const answer = data?.resposta || data?.response || data?.text || "Não consegui gerar uma resposta agora.";\n      conv.messages.push({\n        role:"assistant",\n        content:answer,\n        model:data?.model || null,\n        at:new Date().toISOString()\n      });\n      saveHistory(state.history);\n      renderMessages();\n    }catch(err){\n      thinking.remove();\n      conv.messages.push({\n        role:"assistant",\n        content:`Não consegui falar com a IA agora. ${err?.message || ""}`.trim(),\n        at:new Date().toISOString()\n      });\n      saveHistory(state.history);\n      renderMessages();\n    }\n  }\n\n  function syncFloatingToggle(){\n    const toggle = $("#mentor-ai-floating-toggle");\n    if(!toggle) return;\n    toggle.checked = !!state.settings.floatingEnabled;\n    toggle.onchange = () => {\n      state.settings.floatingEnabled = toggle.checked;\n      saveSettings(state.settings);\n      $("#mentor-ai-floating")?.classList.toggle("mentor-ai-hidden", !toggle.checked);\n      $("#mentor-ai-nudge")?.remove();\n    };\n  }\n\n  function flattenProfile(obj, depth=0, out=[]){\n    if(depth > 4 || obj == null) return out;\n    if(Array.isArray(obj)){\n      obj.forEach(x => flattenProfile(x, depth+1, out));\n      return out;\n    }\n    if(typeof obj === "object"){\n      const name = obj.disciplina || obj.subject || obj.nome || obj.name;\n      const score = obj.media_percentual ?? obj.percentual ?? obj.media ?? obj.score;\n      if(name && Number.isFinite(Number(score))){\n        out.push({name:String(name), score:Number(score)});\n      }\n      Object.values(obj).forEach(x => flattenProfile(x, depth+1, out));\n    }\n    return out;\n  }\n\n  async function fetchProfile(){\n    try{\n      const res = await fetch(CFG.profileUrl,{\n        headers:apiHeaders(),\n        credentials:"same-origin"\n      });\n      if(!res.ok) return;\n      const data = await res.json();\n      state.profile = data;\n      const rows = flattenProfile(data);\n      const unique = [];\n      const seen = new Set();\n      rows.forEach(r => {\n        const k = normalize(r.name);\n        if(!seen.has(k)){seen.add(k); unique.push(r)}\n      });\n      unique.sort((a,b)=>a.score-b.score);\n      if(unique.length){\n        state.lowestSubject = unique[0].name;\n        const improve = $("#mentor-ai-improve");\n        const strong = $("#mentor-ai-strong");\n        const suggestion = $("#mentor-ai-suggestion");\n        const alert = $("#mentor-ai-alert-content");\n        const recommend = $("#mentor-ai-recommend-content");\n        if(improve) improve.textContent = `${unique[0].name} merece mais atenção (${formatPct(unique[0].score)}).`;\n        if(strong && unique.length > 1){\n          const best = unique[unique.length-1];\n          strong.textContent = `${best.name} aparece como um dos seus melhores desempenhos (${formatPct(best.score)}).`;\n        }\n        if(suggestion) suggestion.textContent = `Vamos priorizar ${unique[0].name} e manter o ritmo nas disciplinas em que você já está evoluindo.`;\n        if(alert) alert.textContent = `Atenção em ${unique[0].name}: o Mentor identificou que essa disciplina pode precisar de reforço.`;\n        if(recommend) recommend.textContent = `Faça uma revisão curta de ${unique[0].name} e depois resolva exercícios guiados com o Mentor.`;\n      }\n    }catch{}\n  }\n\n  function formatPct(n){\n    const v = Number(n);\n    if(!Number.isFinite(v)) return String(n);\n    return `${String(Math.round(v*10)/10).replace(".",",")}%`;\n  }\n\n  function mount(){\n    if(!shouldMount()) return;\n    createHomeCard();\n    createNavItem();\n    createFloating();\n    createOverlay();\n    fetchProfile();\n\n    // Pequena tentativa extra para dashboards que renderizam via JS após o load.\n    const observer = new MutationObserver(() => {\n      createHomeCard();\n      createNavItem();\n    });\n    observer.observe(document.body,{childList:true,subtree:true});\n    setTimeout(()=>observer.disconnect(),12000);\n  }\n\n  if(document.readyState === "loading"){\n    document.addEventListener("DOMContentLoaded", mount);\n  }else{\n    mount();\n  }\n})();\n'

css_path.write_text(CSS, encoding="utf-8")
js_path.write_text(JS, encoding="utf-8")

html_files = list(FRONT.rglob("*.html"))
if not html_files:
    raise SystemExit("Nenhum arquivo HTML encontrado dentro de frontend.")

changed = []
for html in html_files:
    text = html.read_text(encoding="utf-8-sig", errors="ignore")
    original = text

    # Evita duplicar.
    if CSS_NAME not in text:
        link = f'\n<link rel="stylesheet" href="{CSS_NAME if html.parent == FRONT else str(Path("..") / CSS_NAME).replace("\\\\","/")}">\n'
        if "</head>" in text:
            text = text.replace("</head>", link + "</head>", 1)

    if JS_NAME not in text:
        src = JS_NAME if html.parent == FRONT else str(Path("..") / JS_NAME).replace("\\","/")
        tag = f'\n<script src="{src}" defer></script>\n'
        if "</body>" in text:
            text = text.replace("</body>", tag + "</body>", 1)

    if text != original:
        backup = html.with_suffix(html.suffix + ".backup_mentor_ai")
        if not backup.exists():
            backup.write_text(original, encoding="utf-8")
        html.write_text(text, encoding="utf-8")
        changed.append(str(html))

